    correction: [{"quoi":"نقسم المعامل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">36 = 6 × 6</span>"},{"quoi":"نقسم الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">36 = 6 × 6</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">36n + 36 = 6(6n + 6)</span>"},{"quoi":"نستنتج","math":"العبارة مكتوبة <span dir=\"ltr\" class=\"expr\">6 ×</span> عدد صحيح، مهما يكن n"},{"quoi":"الجواب","math":"صواب"}],
