    correction: [{"quoi":"نبحث عن الخارج","math":"أكبر مضاعف لـ 11 لا يفوق 6583 هو <span dir=\"ltr\" class=\"expr\">11 × 598</span>"},{"quoi":"نحسب هذا المضاعف","math":"<span dir=\"ltr\" class=\"expr\">11 × 598 = 6578</span>"},{"quoi":"نحسب الباقي","math":"<span dir=\"ltr\" class=\"expr\">6583 - 6578 = 5</span>"},{"quoi":"نتحقّق من الشرط","math":"<span dir=\"ltr\" class=\"expr\">5 &lt; 11</span>"},{"quoi":"نكتب القسمة الإقليدية","math":"<span dir=\"ltr\" class=\"expr\">6583 = 11 × 598 + 5</span>"},{"quoi":"الجواب","math":"صواب"}],
