    correction: [{"quoi":"شرط الباقي","math":"الباقي في القسمة على 4 يجب أن يكون أصغر تماما من 4"},{"quoi":"نقارن","math":"<span dir=\"ltr\" class=\"expr\">6 &gt; 4</span>"},{"quoi":"العدد المقترح ليس باقيا","math":"العدد 6 لا يمكن أن يكون باقي قسمة على 4"},{"quoi":"نُظهر الباقي الحقيقي","math":"<span dir=\"ltr\" class=\"expr\">6 = 4 × 1 + 2</span>"},{"quoi":"نعيد كتابة x","math":"<span dir=\"ltr\" class=\"expr\">12y + 6 = 4(3y + 1) + 2</span>"},{"quoi":"الباقي الحقيقي","math":"الباقي هو 2 لأنّ 2 < 4"},{"quoi":"الجواب","math":"خطأ"}],
