    correction: [{"quoi":"شرط الباقي","math":"الباقي في القسمة على 9 يجب أن يكون أصغر تماما من 9"},{"quoi":"نقارن","math":"<span dir=\"ltr\" class=\"expr\">12 &gt; 9</span>"},{"quoi":"العدد المقترح ليس باقيا","math":"العدد 12 لا يمكن أن يكون باقي قسمة على 9"},{"quoi":"نُظهر الباقي الحقيقي","math":"<span dir=\"ltr\" class=\"expr\">12 = 9 × 1 + 3</span>"},{"quoi":"نعيد كتابة x","math":"<span dir=\"ltr\" class=\"expr\">18y + 12 = 9(2y + 1) + 3</span>"},{"quoi":"الباقي الحقيقي","math":"الباقي هو 3 لأنّ 3 < 9"},{"quoi":"الجواب","math":"خطأ"}],
