    correction: [{"quoi":"نبحث عن الخارج","math":"أكبر مضاعف لـ 7 لا يفوق 2255 هو <span dir=\"ltr\" class=\"expr\">7 × 322</span>"},{"quoi":"نحسب هذا المضاعف","math":"<span dir=\"ltr\" class=\"expr\">7 × 322 = 2254</span>"},{"quoi":"نحسب الباقي","math":"<span dir=\"ltr\" class=\"expr\">2255 - 2254 = 1</span>"},{"quoi":"نتحقّق من الشرط","math":"<span dir=\"ltr\" class=\"expr\">1 &lt; 7</span>"},{"quoi":"نكتب القسمة الإقليدية","math":"<span dir=\"ltr\" class=\"expr\">2255 = 7 × 322 + 1</span>"},{"quoi":"الجواب","math":"صواب"}],
