    enonce: "بيّن أنّ العدد 1366825428 يقبل القسمة على 18",
    correction: [{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">18 = 2 × 9</span> و العددان أوليان فيما بينهما"},{"quoi":"شرط القسمة على 2","math":"العدد يقبل القسمة على 2 إذا كان رقم آحاده زوجي"},{"quoi":"نتحقّق من الشرط الأوّل","math":"نهاية العدد هي 8 و هي تقبل القسمة على 2"},{"quoi":"شرط القسمة على 9","math":"العدد يقبل القسمة على 9 إذا كان مجموع أرقامه يقبل القسمة على 9"},{"quoi":"نحسب مجموع الأرقام","math":"<span dir=\"ltr\" class=\"expr\">1 + 3 + 6 + 6 + 8 + 2 + 5 + 4 + 2 + 8 = 45</span>"},{"quoi":"نتحقّق من الشرط الثاني","math":"45 يقبل القسمة على 9"},{"quoi":"النتيجة","math":"العدد يقبل القسمة على 2 و على 9 و هما أوليان فيما بينهما، فهو يقبل القسمة على 18"}],
