    correction: [{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نوحّد الأساس في الحدّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">4<sup>679</sup> = 2<sup>1358</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">2<sup>1358</sup> + n × 2<sup>1355</sup> = 2<sup>1355</sup>(2<sup>3</sup> + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">20 = 4 × 5</span>"},{"quoi":"العامل 4 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">2<sup>1355</sup> = 2<sup>2</sup> × 2<sup>1353</sup></span>"},{"quoi":"يبقى الشرط على 5","math":"بما أنّ 5 و 2 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">2<sup>3</sup> + n</span> القسمة على 5"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">2<sup>3</sup> = 8</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 60 بحيث يقبل <span dir=\"ltr\" class=\"expr\">8 + n</span> القسمة على 5"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 2 ؛ 7 ؛ 12 ؛ 17 ؛ 22 ؛ 27 ؛ 32 ؛ 37 ؛ 42 ؛ 47 ؛ 52 ؛ 57</span>"}],
